import math

def can_be_product_of_two_squares(n):
    if n < 0:
        return False
    sqrt_n = int(math.sqrt(n))
    if sqrt_n * sqrt_n == n:
        return True
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % (i * i) == 0:
            sqrt_i = int(math.sqrt(i))
            if sqrt_i * sqrt_i == i and n // (i * i) == 1:
                return True
            sqrt_j = int(math.sqrt(n // (i * i)))
            if sqrt_j * sqrt_j == n // (i * i):
                return True
    return False
```

